import { Component, computed, inject, input } from '@angular/core';
import { toObservable, toSignal } from '@angular/core/rxjs-interop';
import { Router } from '@angular/router';
import { catchError, EMPTY, map, Observable, switchMap } from 'rxjs';
import { CinemaApi } from '../core/cinema-api';
import { showDate } from '../core/dates';
import { Movie, Screening } from '../core/models';
import { auditoriumLayout, cellKey, cellState, RowLayout, Cell, SeatState } from '../core/seats';

interface SeatMapView {
  screening: Screening;
  movie: Movie;
}

@Component({
  selector: 'app-seat-map',
  templateUrl: './seat-map.html',
  styleUrl: './seat-map.scss',
})
export class SeatMap {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);

  readonly id = input.required<string>();

  readonly layout: RowLayout[] = auditoriumLayout();
  readonly view = toSignal(toObservable(this.id).pipe(switchMap((id) => this.load(Number(id))))
  , { initialValue: null as SeatMapView | null });

  readonly occupied = computed(() => new Set(this.view()?.screening.occupiedSeats ?? []));
  readonly selected = computed(() => new Set<string>());

  readonly showDate = computed(() => {
    const screening = this.view()?.screening;
    return screening ? showDate(screening.date, screening.time) : '';
  });

  stateOf(cell: Cell): SeatState {
    return cellState(cell, this.occupied(), this.selected());
  }

  cellKey(cell: Cell): string {
    return cellKey(cell);
  }

  private load(id: number): Observable<SeatMapView> {
    return this.api.screening(id).pipe(
      switchMap((screening) => this.api.movie(screening.movieId).pipe(map((movie) => ({ screening, movie })))),
      catchError(() => {
        this.router.navigate(['/']);
        return EMPTY;
      }),
    );
  }
}

@if (view()) {
<main class="page">
  <h1 class="title" data-testid="seat-map-title">Choose your seats</h1>
  <p class="subtitle" data-testid="seat-map-subtitle">Show Date: {{ showDate() }}</p>
  <p class="limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>

  <div class="auditorium">
    <div class="screen" data-testid="screen-indicator">SCREEN</div>
    <div class="seat-map" data-testid="seat-map">
      @for (row of layout; track row.row) {
        <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.row">
          <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.row">{{ row.row }}</span>
          @for (block of row.blocks; track $index; let index = $index) {
            @if (index > 0) {
              <div class="aisle" data-testid="aisle" [attr.data-row]="row.row"></div>
            }
            @if (index === 0 && row.entrance) {
              <div class="entrance"></div>
            } @else {
              <div class="block">
                @for (cell of block; track cellKey(cell)) {
                  @if (cell.kind === 'seat') {
                    <button type="button" class="seat" data-testid="seat" [attr.data-row]="cell.row" [attr.data-column]="cell.column" [attr.data-state]="stateOf(cell)">{{ cell.column }}</button>
                  } @else {
                    <button type="button" class="couch" data-testid="couch" [attr.data-row]="cell.row" [attr.data-column-start]="cell.start" [attr.data-column-end]="cell.end" [attr.data-state]="stateOf(cell)">{{ cell.start }}-{{ cell.end }}</button>
                  }
                }
              </div>
            }
          }
          <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.row">{{ row.row }}</span>
        </div>
      }
    </div>
  </div>
</main>

