.page {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 24px;
}

.title {
  margin: 0;
  font-size: 28px;
  font-weight: 500;
}

.subtitle,
.limit {
  margin: 0;
  text-align: center;
}

.limit {
  color: #555;
}

.auditorium {
  --seat-size: 32px;
  --gap: 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.screen {
  width: 640px;
  padding: 6px 0;
  border-radius: 4px;
  background: #e0e0e0;
  text-align: center;
  font-size: 14px;
  letter-spacing: 4px;
  color: #424242;
